  // RVP: decide el cierre, y la PSAP del eco no.
  const rvp5 = e({ izq:'leve', rvp:5 }), rvp4 = e({ izq:'leve', rvp:4 }), rvp2 = e({ izq:'leve', rvp:2 });
  const htpSinRvp = e({ izq:'leve', htp:'severa' });
  const down = e({ izq:'leve', down:'si' });
